it('button is submit-typed and clickable', () => {
  const btn = container.querySelector('button[data-part=root]');
  expect(btn).toBeTruthy(); expect(btn.type).toBe('submit');
  expect(btn.disabled).toBe(false); expect(btn.getAttribute('aria-busy')).toBeNull();
  let clicked = false; btn.addEventListener('click', () => { clicked = true; });
  btn.click(); expect(clicked).toBe(true);
});
